function authorStreamIdFromWire(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const normalized = value.trim().toLowerCase();
  return /^[0-9a-f]{32}$/.test(normalized) && value === normalized
    ? normalized
    : null;
}

