export type ReticulumDirectCallHistoryWire = {
  c: string;
  q: string;
  d: 'i' | 'o';
  o: 'a' | 'd' | 'm' | 'c' | 'n';
  b: number;
  e: number;
  n: number;
  p: string;
  z: string;
};

function buildDirectCallHistorySignedFields(
  record: Omit<
    ReticulumDirectCallHistoryRecord,
    'conversationId' | 'authorPublicKey' | 'signature' | 'readAt'
  >
): Record<string, unknown> {
  return {
    type: 'RCHAT_DIRECT_CALL_HISTORY_V1',
    ownerAddress: record.ownerAddress,
    callId: record.callId,
    peerAddress: record.peerAddress,
    direction: record.direction,
    outcome: record.outcome,
    startedAt: record.startedAt,
    endedAt: record.endedAt,
    updatedAt: record.updatedAt,
  };
}

function directCallHistoryRecordToWire(
  record: ReticulumDirectCallHistoryRecord
): ReticulumDirectCallHistoryWire {
  const outcomes: Record<
    ReticulumDirectCallHistoryOutcome,
    ReticulumDirectCallHistoryWire['o']
  > = {
    answered: 'a',
    declined: 'd',
    missed: 'm',
    cancelled: 'c',
    no_answer: 'n',
  };
  return {
    c: record.callId,
    q: record.peerAddress,
    d: record.direction === 'incoming' ? 'i' : 'o',
    o: outcomes[record.outcome],
    b: record.startedAt,
    e: record.endedAt,
    n: record.updatedAt,
    p: record.authorPublicKey,
    z: record.signature,
  };
}

export function verifyReticulumDirectCallHistoryWire(
  wire: ReticulumDirectCallHistoryWire,
  now = Date.now()
): ReticulumDirectCallHistoryRecord | null {
  try {
    const ownerAddress = deriveAddressFromPublicKey(wire.p);
    const peerAddress = String(wire.q || '').trim();
    const callId = String(wire.c || '').trim();
    const startedAt = Math.floor(Number(wire.b));
    const endedAt = Math.floor(Number(wire.e));
    const updatedAt = Math.floor(Number(wire.n));
    const outcomes: Record<
      ReticulumDirectCallHistoryWire['o'],
      ReticulumDirectCallHistoryOutcome
    > = {
      a: 'answered',
      d: 'declined',
      m: 'missed',
      c: 'cancelled',
      n: 'no_answer',
    };
    const direction: ReticulumDirectCallHistoryDirection | null =
      wire.d === 'i' ? 'incoming' : wire.d === 'o' ? 'outgoing' : null;
    const outcome = outcomes[wire.o];
    const conversationId = reticulumDmConversationId(ownerAddress, peerAddress);
    if (
      !isValidQortalAddress(ownerAddress) ||
      !isValidQortalAddress(peerAddress) ||
      ownerAddress === peerAddress ||
      !conversationId ||
      !/^[A-Za-z0-9_-]{8,80}$/.test(callId) ||
      !direction ||
      !outcome ||
      !Number.isSafeInteger(startedAt) ||
      !Number.isSafeInteger(endedAt) ||
      !Number.isSafeInteger(updatedAt) ||
      startedAt <= 0 ||
      endedAt < startedAt ||
      updatedAt < endedAt ||
      updatedAt > now + RETICULUM_CHAT_CONTROL_MAX_FUTURE_SKEW_MS ||
      startedAt < now - RETICULUM_CHAT_MAX_AGE_MS ||
      typeof wire.z !== 'string' ||
      !wire.z
    )
      return null;
    const unsigned = {
      ownerAddress,
      callId,
      peerAddress,
      direction,
      outcome,
      startedAt,
      endedAt,
      updatedAt,
    };
    const fields = {
      ...buildDirectCallHistorySignedFields(unsigned),
      authorAddress: ownerAddress,
      authorPublicKey: wire.p,
    };
    if (
      !verifyEd25519Detached(
        new Uint8Array(canonicalizeForSigning(fields)),
        new Uint8Array(base58Decode(wire.z)),
        new Uint8Array(base58Decode(wire.p))
      )
    )
      return null;
    return {
      ...unsigned,
      conversationId,
      authorPublicKey: wire.p,
      signature: wire.z,
      readAt: 0,
    };
  } catch {
    return null;
  }
}

export function buildReticulumChatReadSyncSignedFields(input: {
  scopeType: 'group' | 'dm';
  ownerAddress: string;
  groupId?: number;
  channelId?: string;
  conversationId?: string;
  peerAddress?: string;
  upToTimestamp: number;
  signedAt: number;
}): Record<string, unknown> {
  return {
    type: 'RCHAT_READ_SYNC_V1',
    scopeType: input.scopeType,
    ownerAddress: input.ownerAddress,
    ...(input.scopeType === 'group'
      ? {
          groupId: input.groupId,
          channelId: input.channelId,
        }
      : {
          conversationId: input.conversationId,
          peerAddress: input.peerAddress,
        }),
    upToTimestamp: input.upToTimestamp,
    signedAt: input.signedAt,
  };
}

export function verifyReticulumChatReadSyncWire(
  wire: ReticulumChatReadSyncWire,
  now = Date.now()
): ReticulumChatDeviceReadState | null {
  try {
    const ownerAddress = deriveAddressFromPublicKey(wire.p);
    const upToTimestamp = Math.floor(Number(wire.u));
    const signedAt = Math.floor(Number(wire.n));
    if (
      !isValidQortalAddress(ownerAddress) ||
      !Number.isSafeInteger(upToTimestamp) ||
      upToTimestamp <= 0 ||
      upToTimestamp > now + RETICULUM_CHAT_MAX_FUTURE_SKEW_MS ||
      !Number.isSafeInteger(signedAt) ||
      signedAt <= 0 ||
      signedAt > now + RETICULUM_CHAT_CONTROL_MAX_FUTURE_SKEW_MS ||
      typeof wire.z !== 'string' ||
      !wire.z
    ) {
      return null;
    }
    let state: ReticulumChatDeviceReadState;
    if (wire.y === 'g') {
      const groupId = Number(wire.g);
      const channelId = normalizeReticulumChatChannelId(wire.c);
      if (
        !Number.isSafeInteger(groupId) ||
        groupId <= 0 ||
        !channelId ||
        typeof wire.c !== 'string' ||
        wire.c.trim().toLowerCase() !== channelId
      ) {
        return null;
      }
      state = {
        ownerAddress,
        scopeType: 'group',
        scopeId: `${groupId}:${channelId}`,
        groupId,
        channelId,
        upToTimestamp,
        signedAt,
        authorPublicKey: wire.p,
        signature: wire.z,
      };
    } else if (wire.y === 'd') {
      const peerAddress = String(wire.q || '').trim();
      const conversationId = reticulumDmConversationId(
        ownerAddress,
        peerAddress
      );
      const suppliedConversationId =
        wire.c == null ? '' : normalizeReticulumDmConversationId(wire.c);
      if (
        !conversationId ||
        !isValidQortalAddress(peerAddress) ||
        peerAddress === ownerAddress ||
        (wire.c != null && suppliedConversationId !== conversationId)
      ) {
        return null;
      }
      state = {
        ownerAddress,
        scopeType: 'dm',
        scopeId: conversationId,
        conversationId,
        peerAddress,
        upToTimestamp,
        signedAt,
        authorPublicKey: wire.p,
        signature: wire.z,
      };
    } else {
      return null;
    }
    const fields = {
      ...buildReticulumChatReadSyncSignedFields(state),
      authorAddress: ownerAddress,
      authorPublicKey: wire.p,
    };
    return verifyEd25519Detached(
      new Uint8Array(canonicalizeForSigning(fields)),
      new Uint8Array(base58Decode(wire.z)),
      new Uint8Array(base58Decode(wire.p))
    )
      ? state
      : null;
  } catch {
    return null;
  }
}

